fn digits(v:&[i64],a:usize,b:usize)->Option<i64>{let mut x=0;for &c in &v[a..b]{if !(48..=57).contains(&c){return None}x=x*10+c-48}Some(x)}
#[no_mangle]
pub unsafe extern "C" fn parse_date(v:*const i64,n:usize)->i64{if v.is_null()||n<9||n>11{return -1}let a=std::slice::from_raw_parts(v,n);if !(8..=10).contains(&a[0])||n!=a[0]as usize+1||a[1..].iter().any(|x|!(0..=127).contains(x)){return -1}let len=a[0]as usize;let slashes:Vec<usize>=a[1..].iter().enumerate().filter_map(|(i,&c)|(c==47).then_some(i+1)).collect();if slashes.len()!=2{return -1}let(s1,s2)=(slashes[0],slashes[1]);if !(2..=3).contains(&s1)||!(2..=3).contains(&(s2-s1))||len-s2!=4{return -1}let(Some(d),Some(m),Some(y))=(digits(a,1,s1),digits(a,s1+1,s2),digits(a,s2+1,len+1))else{return -1};if !(1..=12).contains(&m){return -1}let mut days=[31,28,31,30,31,30,31,31,30,31,30,31];if m==2&&y%4==0&&(y%100!=0||y%400==0){days[1]=29}if d<1||d>days[m as usize-1]{return -1}y*10000+m*100+d}
